if(f.kind==='window'){const L=G.dist(a,b),n=[-(b[1]-a[1])/L*t*.28,(b[0]-a[0])/L*t*.28];out+=[-1,1].map(s=>`<path d="M${a.map((v,i)=>v+n[i]*s)} L${b.map((v,i)=>v+n[i]*s)}" stroke="#fff" stroke-width="${pxScale()*.8}"/>`).join('');}
out+=`<path class="wall-hit ${f.host_wall_id?'opening-hit':''}" d="M${a} L${b}" stroke="transparent" stroke-width="${Math.max(t,pxScale()*12)}" fill="none"/>`;
