function openingDimensions(o,fs){
 const w=fs.find(w=>w.id===o.host_wall_id);if(!w)return '';const [a,b]=w.points,L=G.dist(a,b),u=b.map((v,i)=>(v-a[i])/L),n=[-u[1],u[0]],px=pxScale(),at=(t,h)=>a.map((v,i)=>v+u[i]*t+n[i]*h);
 const corners=[at(o.offset,-w.thickness/2-2*px),at(o.offset+o.width,-w.thickness/2-2*px),at(o.offset+o.width,w.thickness/2+2*px),at(o.offset,w.thickness/2+2*px)];
 let out=`<g id="opening-dimensions" pointer-events="none" data-offset="${o.offset}" data-end-gap="${L-o.offset-o.width}"><path d="M${corners.join(' L')} Z" fill="none" stroke="#245dcc" stroke-width="${2*px}"/>`;
 const h=w.thickness/2+24*px;
 for(const [lo,hi,label] of [[0,o.offset,'A'],[o.offset+o.width,L,'B']]){const ps=[at(lo,h),at(hi,h)],mid=at((lo+hi)/2,h-6*px);out+=`<path d="M${ps[0]} L${ps[1]} M${at(lo,h-4*px)} L${at(lo,h+4*px)} M${at(hi,h-4*px)} L${at(hi,h+4*px)}" stroke="#245dcc" stroke-width="${px}" fill="none"/>`;if((hi-lo)/px>65)out+=`<text pointer-events="none" class="length-label" x="${mid[0]}" y="${mid[1]}" text-anchor="middle" font-size="${11*px}">${label}: ${esc(length(hi-lo))}</text>`;}
 for(const [t,label] of [[0,'A'],[L,'B']]){const p=at(t,-w.thickness/2-16*px);out+=`<text pointer-events="none" class="endpoint-letter" x="${p[0]}" y="${p[1]}" text-anchor="middle" font-size="${10*px}">${label}</text>`;}
 const c=O.clearances(fs,o);for(const [gap,t,label] of [[c.left,o.offset,'Previous'],[c.right,o.offset+o.width,'Next']])if(gap!==null){const lo=label==='Previous'?t-gap:t,hi=label==='Previous'?t:t+gap;out+=dimension(at(lo,h+22*px),at(hi,h+22*px),label+' '+length(gap));}
 return out+'</g>';
}
function updateOpeningReadout(){const f=selectedFeature();if(!f||!O.isOpening(f))return;
 if($('#opening-offset'))$('#opening-offset').value=inputLength(f.offset);if($('#opening-width'))$('#opening-width').value=inputLength(f.width);
 const clear=O.clearances(doc.features,f);if($('#opening-distances')&&clear)$('#opening-distances').textContent='A → edge: '+length(clear.a)+' · Other edge → B: '+length(clear.b);if($('#opening-height'))$('#opening-height').value=inputMetres(O.levels(f).height);if($('#opening-base'))$('#opening-base').value=inputMetres(O.levels(f).base);if($('#live-measurements'))$('#live-measurements').textContent=liveSummary(f);
}

function visibleFeatures(fs){const opens=fs.filter(f=>['door','window','sliding_door'].includes(f.kind));return fs.flatMap(f=>{if(f.kind!=='wall')return [f];let pieces=[f];for(const o of opens){if(o.host_wall_id&&o.host_wall_id!==f.id)continue;pieces=pieces.flatMap(w=>DrawingGeometry.cutOpening(w,o,()=>f.id)||[w]);}return pieces.map(p=>({...p,id:f.id}));});}
