const opening=fs.find(f=>f.id===selected&&O.isOpening(f));if(opening&&overlay==='corrected')html+=openingDimensions(opening,fs)+planOpeningTools(opening,fs);
const sel=fs.find(f=>f.id===selected);if(sel?.kind==='wall'&&!selectedObject()){const p=sel.points[0].map((v,i)=>(v+sel.points[1][i])/2);html+=`<text class="length-label" pointer-events="none" x="${p[0]}" y="${p[1]-(p[1]<view[1]+65*pxScale()?-32:20)*pxScale()}" font-size="${11*pxScale()}" text-anchor="middle">${esc(liveSummary(sel))}</text>`;}if(overlay==='corrected'){
 const rows=selectedObject()?[]:joinSource?G.junctions(fs).filter(f=>f.kind==='wall'):G.junctions(fs).filter(f=>f.kind==='wall'&&(!f.wall_chain_id||editingChain===f.wall_chain_id)&&(wallSelection.has(f.id)||f.id===sel?.id)),seen=new Set();
 for(const w of rows)for(const anchor of G.anchors(w)){const {point:p,index:i,id:key}=anchor,members=G.members(fs,w.id,i);if(seen.has(key))continue;seen.add(key);const label=i===0?'A':i===1?'B':'',description=(label?'End '+label:'Branch junction')+` · ${members.length} connected wall member(s) · click to continue, drag to move`;
 html+=`<g class="endpoint-target" data-feature="${esc(w.id)}" data-endpoint="${i}" data-members="${members.length}" tabindex="0" role="button" aria-label="${esc(description)}"><title>${esc(description)}</title><circle fill="transparent" stroke="none" cx="${p[0]}" cy="${p[1]}" r="${11*pxScale()}"/><circle class="endpoint ${members.length>1?'shared-junction':''}" pointer-events="none" cx="${p[0]}" cy="${p[1]}" r="${pxScale()*3.5}"/></g>`;
 if(label&&(rows.length===1||w.id===selected))html+=`<text class="endpoint-letter" pointer-events="none" x="${p[0]+9*pxScale()}" y="${p[1]-9*pxScale()}" font-size="${10*pxScale()}">${label}</text>`;
 }

}

const line=measure.length===2?measure:c?.points;if(line){html+=`<path d="M${line[0]} L${line[1]}" pointer-events="none" stroke="#875ec5" stroke-width="${pxScale()*1.5}" stroke-dasharray="${pxScale()*5} ${pxScale()*3}" fill="none"/>${!bg.visible?`<text pointer-events="none" class="length-label" x="${(line[0][0]+line[1][0])/2}" y="${(line[0][1]+line[1][1])/2-8*pxScale()}" font-size="${11*pxScale()}" text-anchor="middle">${measure.length===2?'Confirm real length':esc(fmt(c.metres))}</text>`:''}`;}
